function validate([prizePositions, k]) {
  const n = prizePositions.length;
  if (n < 1 || n > 100000) return 'prizePositions needs 1 to 10^5 values.';
  for (let i = 0; i < n; i++) {
    const p = prizePositions[i];
    if (!Number.isInteger(p) || p < 1 || p > 1000000000) return 'Each position is a whole number from 1 to 10^9.';
    if (i > 0 && p < prizePositions[i - 1]) return 'prizePositions must be sorted in non-decreasing order.';
  }
  if (!Number.isInteger(k) || k < 0 || k > 1000000000) return 'k is a whole number from 0 to 10^9.';
  return null;
}

