function maximizeWin(prizePositions, k) {
  const n = prizePositions.length;
  // best[i] = most prizes one segment can win using only the first i prizes.
  const best = new Array(n + 1).fill(0);
  let answer = 0;
  let left = 0;

  for (let right = 0; right < n; right++) {
    while (prizePositions[right] - prizePositions[left] > k) {
      left++;
    }
    const count = right - left + 1;
    answer = Math.max(answer, count + best[left]);
    best[right + 1] = Math.max(best[right], count);
  }
  return answer;
}

