function maximizeWin(prizePositions, k) {
  const starts = [...new Set(prizePositions)];
  let most = 0;
  for (const a of starts) {
    for (const b of starts) {
      let won = 0;
      for (const p of prizePositions) {
        if ((p >= a && p <= a + k) || (p >= b && p <= b + k)) won++;
      }
      most = Math.max(most, won);
    }
  }
  return most;
}

