function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const maxGap = [0, 3, 1000, 500000][int(0, 3)];
    const positions = [];
    let pos = int(1, 1000);
    for (let i = 0; i < n; i++) {
      positions.push(pos);
      pos = Math.min(1000000000, pos + int(0, maxGap));
    }
    const k = rand() < 0.1 ? 1000000000 : int(0, Math.max(1, maxGap) * 40);
    return [positions, k];
  }
  const n = int(1, 10);
  const span = int(1, 20);
  const positions = Array.from({ length: n }, () => int(1, span)).sort((a, b) => a - b);
  const k = rand() < 0.2 ? 0 : int(0, 8);
  return [positions, k];
}
